using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Text;
using System.Web.Script.Serialization;

internal static class UpdateVerification {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static string Metadata(string version="1.13.0",bool draft=false,bool prerelease=false,string digest=null){string name="Aion-2-Helper-v"+version+"-windows-x64.zip";return new JavaScriptSerializer().Serialize(new{tag_name="v"+version,name="Test release",draft=draft,prerelease=prerelease,assets=new object[]{new{name=name,size=100,browser_download_url="https://github.com/"+UpdateManager.Repository+"/releases/download/v"+version+"/"+name,digest=digest??"sha256:"+new string('a',64)}}});}
    static void Rejected(Action action,string message){bool rejected=false;try{action();}catch(InvalidDataException){rejected=true;}Check(rejected,message);}
    static void Add(ZipArchive zip,string path,byte[] bytes){var entry=zip.CreateEntry(path);using(var stream=entry.Open())stream.Write(bytes,0,bytes.Length);}
    static string Package(string folder,string extra=null){string archive=Path.Combine(folder,"package.zip");using(var zip=ZipFile.Open(archive,ZipArchiveMode.Create)){Add(zip,"Aion2Helper.exe",File.ReadAllBytes(Assembly.GetExecutingAssembly().Location));Add(zip,"protocol/sync-opcodes.json",Encoding.UTF8.GetBytes("{}"));Add(zip,"tools/presentmon/PresentMon.exe",new byte[]{1,2,3});Add(zip,"assets/sounds/party-invite.mp3",new byte[]{4,5,6});Add(zip,"README.md",Encoding.UTF8.GetBytes("New readme"));if(extra!=null)Add(zip,extra,new byte[]{9});}return archive;}
    static string Folder(string root,string name){string folder=Path.Combine(root,name);Directory.CreateDirectory(folder);return folder;}
    static string Installation(string root){string folder=Folder(root,"installation");File.WriteAllText(Path.Combine(folder,"Aion2Helper.exe"),"Previous application");File.WriteAllText(Path.Combine(folder,"AionDash.exe"),"Previous alias");File.WriteAllText(Path.Combine(folder,"README.md"),"Previous readme");foreach(string file in new[]{"overlay-settings.json","combat-history.json","game-tweaks.json","game-launch.json","visual-tweaks.json","update-settings.json","pets-state.json","hotbar-profiles.json"})File.WriteAllText(Path.Combine(folder,file),"Keep "+file);return folder;}
    internal static void Run(string root){
        Check(UpdateManager.ParseVersion("v1.10.0")>UpdateManager.ParseVersion("v1.9.0"),"Numeric version comparison, not lexical");Check(UpdateManager.Parse(Metadata(),UpdateManager.CurrentVersion).AssetName=="Aion-2-Helper-v1.13.0-windows-x64.zip","Exact official Windows asset");Rejected(delegate{UpdateManager.Parse(Metadata(draft:true),UpdateManager.CurrentVersion);},"Draft releases excluded");Rejected(delegate{UpdateManager.Parse(Metadata(prerelease:true),UpdateManager.CurrentVersion);},"Prereleases excluded");Rejected(delegate{UpdateManager.Parse(Metadata().Replace("https://github.com/","https://example.com/"),UpdateManager.CurrentVersion);},"Other download hosts rejected");Rejected(delegate{UpdateManager.ParseVersion("1.2.3;echo nope");},"Version cannot contain commands");
        foreach(string path in new[]{"../Aion2Helper.exe","assets/../../Aion2Helper.exe","C:/Aion2Helper.exe","overlay-settings.json","combat-history.json","game-tweaks.json","game-launch.json","visual-tweaks.json","update-settings.json","pets-state.json","hotbar-profiles.json","assets/sounds/party-invite.mp3:evil","unknown.exe"})Check(!UpdateInstaller.Allowed(path),"Unrelated or traversal paths rejected: "+path);
        string study=Folder(root,"update-verification-"+Guid.NewGuid().ToString("N"));var cancellation=new UpdateCancellation();string install=Installation(Folder(study,"success")),stage=Folder(study,"success-stage"),archive=Package(stage);var job=UpdateInstaller.Stage(archive,stage,install,UpdateManager.CurrentVersion,cancellation);UpdateInstaller.Apply(job,delegate{},delegate{UpdateInstaller.VerifyInstalled(job);});Check(UpdateManager.Hash(Path.Combine(install,"Aion2Helper.exe"))==UpdateManager.Hash(Assembly.GetExecutingAssembly().Location),"Verified program installed and separate health-check process completed");Check(UpdateManager.Hash(Path.Combine(install,"AionDash.exe"))==UpdateManager.Hash(Assembly.GetExecutingAssembly().Location),"Existing aliases updated");Check(File.ReadAllText(Path.Combine(install,"README.md"))=="New readme","Program resources replaced");foreach(string file in new[]{"overlay-settings.json","combat-history.json","game-tweaks.json","game-launch.json","visual-tweaks.json","update-settings.json","pets-state.json","hotbar-profiles.json"})Check(File.ReadAllText(Path.Combine(install,file))=="Keep "+file,"User data survives: "+file);
        foreach(bool healthFailure in new[]{false,true}){string rollbackRoot=Installation(Folder(study,healthFailure?"health-failure":"copy-failure"));string rollbackStage=Folder(study,healthFailure?"health-stage":"copy-stage");var rollback=UpdateInstaller.Stage(Package(rollbackStage),rollbackStage,rollbackRoot,UpdateManager.CurrentVersion,cancellation);bool failed=false;try{UpdateInstaller.Apply(rollback,delegate{},delegate{if(healthFailure)throw new IOException("Simulated health failure");},delegate(int index){if(!healthFailure&&index==2)throw new IOException("Simulated file failure");});}catch(IOException){failed=true;}Check(failed&&File.ReadAllText(Path.Combine(rollbackRoot,"Aion2Helper.exe"))=="Previous application"&&File.ReadAllText(Path.Combine(rollbackRoot,"README.md"))=="Previous readme"&&File.ReadAllText(Path.Combine(rollbackRoot,"AionDash.exe"))=="Previous alias","Copy/startup failure restores previous program and aliases");Check(!File.Exists(Path.Combine(rollbackRoot,"protocol","sync-opcodes.json")),"Rollback removes newly installed program files");}
        string badStage=Folder(study,"bad-stage");Rejected(delegate{UpdateInstaller.Stage(Package(badStage,"overlay-settings.json"),badStage,install,UpdateManager.CurrentVersion,cancellation);},"Packages cannot overwrite preferences");string cancelStage=Folder(study,"cancel-stage");var cancel=new UpdateCancellation();cancel.Cancel();bool cancelled=false;try{UpdateInstaller.Stage(Package(cancelStage),cancelStage,install,UpdateManager.CurrentVersion,cancel);}catch(OperationCanceledException){cancelled=true;}Check(cancelled,"Cancellation stops preparation before install");
        string tamperRoot=Installation(Folder(study,"tamper")),tamperStage=Folder(study,"tamper-stage");var tamper=UpdateInstaller.Stage(Package(tamperStage),tamperStage,tamperRoot,UpdateManager.CurrentVersion,cancellation);File.AppendAllText(Path.Combine(tamperStage,"payload","README.md"),"modified");Rejected(delegate{UpdateInstaller.Apply(tamper,delegate{},delegate{});},"Modified staged files cannot be installed");Check(File.ReadAllText(Path.Combine(tamperRoot,"Aion2Helper.exe"))=="Previous application","Tamper rejection leaves installation untouched");
        foreach(string unsafePath in new[]{"../escape.exe","README.MD"}){string unsafeStage=Folder(study,"unsafe-"+Guid.NewGuid().ToString("N"));Rejected(delegate{UpdateInstaller.Stage(Package(unsafeStage,unsafePath),unsafeStage,install,UpdateManager.CurrentVersion,cancellation);},"Traversal and case-duplicate ZIP entries rejected");}
        var manager=new UpdateManager(Folder(study,"preferences"));Check(manager.Preferences.CheckOnStartup,"Startup checks default on");manager.StartupPreference(false);Check(!new UpdateManager(Path.Combine(study,"preferences")).Preferences.CheckOnStartup,"Startup preference persists separately");
        string designs=Folder(root,"designs");foreach(string language in new[]{"en","es"}){var window=new UpdateWindow(manager,language,false,true);try{window.Render(new UpdateSnapshot{State="Available",Release=UpdateManager.Parse(Metadata(),UpdateManager.CurrentVersion)});SettingsVisual.RenderPreview(window,Path.Combine(designs,"update-available-"+language+".png"));}finally{window.Close();}}
        File.WriteAllText(Path.Combine(root,"updates-test.txt"),"PASS: numeric versions; published-only exact repository assets; checksum metadata; protected user files and ZIP paths; verified staging; program/alias update; preserved settings/history/tweaks; copy and health-check rollback; cancellation; startup preference; EN/ES update previews. No network, game memory or real installation modified.");
    }
    internal static void Live(string root){var release=UpdateManager.Parse(UpdateManager.DownloadText(UpdateManager.LatestUrl,2*1024*1024,new UpdateCancellation()),UpdateManager.CurrentVersion);string folder=Folder(root,"update-live-verification-"+Guid.NewGuid().ToString("N"));string install=Installation(folder),stage=Folder(folder,"stage"),archive=Path.Combine(stage,"download.zip");UpdateManager.Download(release,archive,new UpdateCancellation(),delegate{});var job=UpdateInstaller.Stage(archive,stage,install,release.Version,new UpdateCancellation());File.WriteAllText(Path.Combine(root,"updates-live-test.txt"),"PASS: official published GitHub metadata, "+release.Tag+" Windows archive ("+release.Size+" bytes), verified SHA-256, ZIP validation, executable version and "+job.Files.Count+" allowlisted program files. Download and extraction only; not installed or executed.");}
}
